function drawBoss(){const b=state.boss,wp=getWeakPoint(state);ctx.save();ctx.translate(b.x+b.recoilX,b.y);if(b.flash)ctx.filter='brightness(2.5)';if(state.breakIn){ctx.shadowColor='#ffd85d';ctx.shadowBlur=25;}ctx.fillStyle='#252b3a';ctx.strokeStyle='#d7b65b';ctx.lineWidth=5;ctx.beginPath();ctx.moveTo(-42,38);ctx.lineTo(-34,-16);ctx.lineTo(-18,-48);ctx.lineTo(0,-58);ctx.lineTo(22,-44);ctx.lineTo(40,-12);ctx.lineTo(43,38);ctx.closePath();ctx.fill();ctx.stroke();ctx.fillStyle='#ddb58e';ctx.beginPath();ctx.arc(0,-18,17,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#ee574e';ctx.lineWidth=7;ctx.beginPath();ctx.moveTo(20,-8);ctx.lineTo(55,30);ctx.stroke();ctx.restore();ctx.save();ctx.translate(wp.x,wp.y);ctx.rotate(performance.now()/260);ctx.strokeStyle='#fff38a';ctx.lineWidth=3;ctx.beginPath();for(let i=0;i<8;i++){const a=i*Math.PI/4,r=i%2?7:13;ctx.lineTo(Math.cos(a)*r,Math.sin(a)*r);}ctx.closePath();ctx.stroke();ctx.restore();if(state.boss.move){const p=Math.min(1,state.boss.move.elapsed/state.boss.move.windup);ctx.strokeStyle=`rgba(255,72,76,${.3+p*.7})`;ctx.lineWidth=3+p*8;ctx.beginPath();ctx.arc(state.boss.x,state.boss.y,64+p*13,0,Math.PI*2);ctx.stroke();}}
function trails(form){for(let i=form.length-1;i>=0;i--){const f=form[i];ctx.save();ctx.globalAlpha=Math.min(.65,Math.hypot(state.core.vx,state.core.vy)/750);ctx.strokeStyle=colors[i][0];ctx.lineWidth=6-i;ctx.beginPath();ctx.moveTo(f.x-Math.cos(f.angle)*50,f.y-Math.sin(f.angle)*50);ctx.lineTo(f.x,f.y);ctx.stroke();ctx.restore();}}
function effects(){for(const e of state.events){const a=Math.max(0,Math.min(1,e.life/.7));ctx.save();ctx.globalAlpha=a;ctx.textAlign='center';if(['hit','weak-hit','power-hit'].includes(e.type)){const strong=e.type!=='hit',r=(strong?22:12)+(1-a)*(strong?75:38);ctx.strokeStyle=e.type==='weak-hit'?'#fff36b':e.type==='power-hit'?'#86f5ff':'#fff';ctx.lineWidth=strong?7:4;ctx.beginPath();ctx.arc(e.x,e.y,r,0,Math.PI*2);ctx.stroke();ctx.font=`900 ${strong?25:18}px sans-serif`;ctx.lineWidth=4;ctx.strokeStyle='#10131d';ctx.fillStyle=e.type==='weak-hit'?'#fff06f':'#fff';ctx.strokeText(e.text,e.x,e.y-r*.15);ctx.fillText(e.text,e.x,e.y-r*.15);}else if(e.type==='skill-slash'){ctx.strokeStyle='#4dffc0';ctx.shadowColor='#4dffc0';ctx.shadowBlur=16;ctx.lineWidth=e.phase===2?14:9;ctx.beginPath();ctx.arc(e.x,e.y,64+e.phase*10,-2.8+e.phase*.4,.5+e.phase*.65);ctx.stroke();}else{ctx.font=`900 ${['break','counter','rank','skill-intro'].includes(e.type)?24:18}px sans-serif`;ctx.strokeStyle='#10131d';ctx.lineWidth=5;ctx.fillStyle=e.type==='counter'?'#8ff6ff':e.type==='break'?'#ffe05d':e.type.includes('power')?'#ffe77b':'#fff';ctx.strokeText(e.text||'',e.x,e.y);ctx.fillText(e.text||'',e.x,e.y);}ctx.restore();}}
function render(){ctx.clearRect(0,0,canvas.width,canvas.height);ctx.save();if(state.shake)ctx.translate((Math.random()-.5)*11,(Math.random()-.5)*8);background();drawBoss();const formation=getFormation(state);trails(formation);formation.forEach((f,i)=>hero(f.x,f.y,i,1,i?0.9:1));if(state.skill){hero(state.skill.x,state.skill.y,0,1.18);ctx.save();ctx.globalCompositeOperation='lighter';ctx.strokeStyle='#54ffbb';ctx.lineWidth=10;ctx.beginPath();ctx.moveTo(state.skill.x-48,state.skill.y+22);ctx.lineTo(state.skill.x+35,state.skill.y-26);ctx.stroke();ctx.restore();}effects();ctx.restore();if(state.flash){ctx.fillStyle=`rgba(255,255,255,${Math.min(.3,state.flash*2)})`;ctx.fillRect(0,0,canvas.width,canvas.height);}}
function sync(){ui.time.textContent=state.timeLeft.toFixed(1);ui.combo.textContent=`${state.combo} HIT`;ui.rank.textContent=getComboRank(state.combo);ui.power.style.width=`${state.power}%`;ui.powerLabel.textContent=state.powerTier?`POWER ${state.powerTier===4?'MAX':'ⅠⅡⅢ'[state.powerTier-1]} READY`:'蓄力中';ui.break.style.width=`${state.breakGauge}%`;ui.breakLabel.textContent=state.breakIn?`BREAK ${state.breakIn.toFixed(1)}s`:`弱點：${['左','上','右'][state.boss.weakSide]}`;ui.hint.textContent=getActionHint(state);ui.move.textContent=state.boss.move?`${state.boss.move.name}・看準時機反擊`:state.breakIn?'BREAK 爆發時間':'';ui.move.classList.toggle('show',Boolean(state.boss.move||state.breakIn));if(state.complete&&!result.classList.contains('show')){const r=getResults(state);result.innerHTML=`<h2>${state.boss.hp<=0?'寨主擊破！':'30 秒完成'}</h2><dl><dt>最高 Combo</dt><dd>${r.highestCombo}</dd><dt>FLIP</dt><dd>${r.flips}</dd><dt>Perfect Flip</dt><dd>${r.perfectFlips}</dd><dt>DASH</dt><dd>${r.dashes}</dd><dt>Counter</dt><dd>${r.counters}</dd><dt>Perfect Counter</dt><dd>${r.perfectCounters}</dd><dt>Power Flip</dt><dd>${r.powerFlips}</dd><dt>青龍偃月</dt><dd>${r.skills}</dd><dt>BREAK</dt><dd>${r.breaks}</dd></dl><button type="button">再玩一次</button>`;result.classList.add('show');try{localStorage.setItem(SAVE_KEY,JSON.stringify({last:r,playedAt:Date.now()}));}catch{}result.querySelector('button').onclick=restart;}}
function sound(type){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=type.includes('counter')?520:type.includes('power')?190:290;g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.065);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.07);}catch{}}
